
from web3 import Web3, EthereumTesterProvider

w3 = Web3(EthereumTesterProvider())

abi = [
    {
        "inputs": [
            {"internalType": "string", "name": "_text", "type": "string"},
            {"internalType": "string", "name": "_sentiment", "type": "string"}
        ],
        "name": "saveRecord",
        "outputs": [],
        "stateMutability": "nonpayable",
        "type": "function"
    },
    {
        "inputs": [],
        "name": "getRecord",
        "outputs": [
            {"internalType": "string", "name": "", "type": "string"},
            {"internalType": "string", "name": "", "type": "string"}
        ],
        "stateMutability": "view",
        "type": "function"
    },
    {
        "inputs": [],
        "name": "latestRecord",
        "outputs": [
            {"internalType": "string", "name": "text", "type": "string"},
            {"internalType": "string", "name": "sentiment", "type": "string"}
        ],
        "stateMutability": "view",
        "type": "function"
    }
]

bytecode = ""


if __name__ == "__main__":
    account = w3.eth.accounts[0]

    contract = w3.eth.contract(abi=abi, bytecode=bytecode)

    tx_hash = contract.constructor().transact({"from": account})
    tx_receipt = w3.eth.wait_for_transaction_receipt(tx_hash)

    print("Contract deployed successfully!")
    print("Contract address:", tx_receipt.contractAddress)

    ai_record = w3.eth.contract(
        address=tx_receipt.contractAddress,
        abi=abi
    )

    text_to_save = "This is a great and excellent result"
    sentiment_to_save = "positive"

    tx_hash = ai_record.functions.saveRecord(
        text_to_save,
        sentiment_to_save
    ).transact({"from": account})

    w3.eth.wait_for_transaction_receipt(tx_hash)

    result = ai_record.functions.getRecord().call()

    print("Saved text:", result[0])
    print("Saved sentiment:", result[1])
